<?php $consents=$ortho['consents'] ?? []; $media=$ortho['media'] ?? $ortho['attachments'] ?? []; if(isset($media['all']))$media=$media['all']; $documents=$ortho['documents'] ?? $media; $consentKinds=$catalogs['consent_kinds'] ?? ['treatment'=>'Tratamiento ortodóntico','photography'=>'Fotografías y estudios clínicos','ai_external'=>'Procesamiento externo con IA','data_processing'=>'Tratamiento de datos personales','other'=>'Otro consentimiento']; ?>
<div class="orth-section-intro"><div><h3>Documentos y consentimientos</h3><p>Conserva los soportes originales y registra la autorización o revocación.</p></div><a class="button secondary small" href="<?= e($caseLink('photos').'#orth-upload') ?>">Adjuntar documento</a></div>
<?php if($canWrite): ?><details class="panel orth-form-panel" id="orth-consent"><summary><?= icon('shield',18) ?><span>Registrar un consentimiento</span><small>La revocación conserva el historial</small></summary><form method="post" class="form-grid orth-panel-body" data-orth-dirty data-loading><?php $orthoFields('consent',$case); choose('kind','Alcance del consentimiento',$consentKinds); choose('status','Decisión registrada',['granted'=>'Otorgado','revoked'=>'Revocado'],'granted'); field('signed_on','Fecha del documento',date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"'); ?><label>Documento de soporte<select name="attachment_id"><option value="">Sin adjunto</option><?php foreach($media as $file): ?><option value="<?= (int)($file['attachment_id'] ?? $file['id']) ?>"><?= e($file['original_name'] ?? 'Documento clínico') ?></option><?php endforeach; ?></select></label><?php area('notes','Alcance, fundamento y observaciones del registro','',true); ?><p class="orth-help full">Este registro documenta una decisión clínica. Adjunta el consentimiento firmado y registra cualquier revocación posterior.</p><button class="button">Guardar consentimiento</button></form></details><?php endif; ?>
<section class="panel"><div class="orth-section-heading"><h3>Historial de consentimientos</h3></div><?php if(!$consents): $orthoEmpty('No hay consentimientos registrados','Registra su alcance, fecha y soporte firmado antes de realizar la actividad correspondiente.','shield'); else: ?><div class="table-wrap" role="region" tabindex="0" aria-label="Consentimientos del paciente"><table><thead><tr><th>Alcance</th><th>Decisión</th><th>Fecha</th><th>Observaciones</th><th>Autor / soporte</th></tr></thead><tbody><?php foreach($consents as $consent): ?><tr><td><?= e($consentKinds[$consent['kind']] ?? $consent['kind']) ?></td><td><span class="orth-status <?= ($consent['status'] ?? '')==='granted'?'active':'cancelled' ?>"><?= ($consent['status'] ?? '')==='granted'?'Otorgado':'Revocado' ?></span></td><td><?= $orthoDate($consent['signed_on'] ?? null) ?></td><td><?= nl2br(e($consent['notes'] ?? '')) ?></td><td><?= e($consent['author'] ?? '') ?><?php if(!empty($consent['attachment_id'])): ?><small><a class="orth-link" href="<?= e(url('/admin/attachment?id='.(int)$consent['attachment_id'])) ?>">Descargar soporte</a></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><div class="orth-section-heading"><h3>Documentación clínica</h3></div><?php if(!$documents): $orthoEmpty('Sin documentos adjuntos','Los archivos privados relacionados con el caso aparecerán aquí.','file'); else: ?><div class="orth-document-list"><?php foreach($documents as $file): ?><a href="<?= e(url('/admin/attachment?id='.(int)($file['attachment_id'] ?? $file['id']))) ?>"><?= icon('file',24) ?><span><strong><?= e($file['original_name'] ?? 'Documento') ?></strong><small><?= e($file['description'] ?? '') ?> · <?= local_date($file['created_at'] ?? null,'d/m/Y') ?> · <?= e($file['author'] ?? '') ?></small></span><?= icon('arrow',18) ?></a><?php endforeach; ?></div><?php endif; ?></section>

<?php if($canWrite): ?><section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">ACCESO AL EXPEDIENTE</span><h3>Equipo de apoyo autorizado</h3><p>Los permisos de apoyo permiten gestionar archivos, agenda y tareas de este caso.</p></div></div><form method="post" class="form-grid orth-panel-body" data-loading><?php $orthoFields('member',$case); choose('user_id','Integrante autorizado',array_column($ortho['assignable_users'] ?? [],'name','id')); choose('active','Asignación',['1'=>'Conceder acceso de apoyo','0'=>'Retirar acceso'],'1'); ?><button class="button secondary">Actualizar asignación</button></form><div class="orth-document-list"><?php foreach($ortho['members'] ?? [] as $member): ?><div class="orth-task"><?= icon('users',20) ?><div><strong><?= e($member['name'] ?? '') ?></strong><small><?= !empty($member['active'])?'Acceso de apoyo activo':'Acceso retirado' ?> ? <?= e($member['assigned_by_name'] ?? '') ?></small></div></div><?php endforeach; ?></div></section><?php endif; ?>
